import java.util.Scanner;

public class Main {
    static class Matrix {
        long[][] data;
        int rows, cols;

        Matrix(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            data = new long[rows][cols];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            Matrix C = new Matrix(A.rows, B.cols);
            for (int i = 0; i < A.rows; i++) {
                for (int j = 0; j < B.cols; j++) {
                    long sum = 0;
                    for (int k = 0; k < A.cols; k++) {
                        sum += A.data[i][k] * B.data[k][j];
                    }
                    C.data[i][j] = sum;
                }
            }
            return C;
        }
    }

    public static void initializeMatrix(Matrix A, int rows, int cols) {
        A.rows = rows;
        A.cols = cols;
        A.data = new long[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                A.data[i][j] = 0;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        int K = sc.nextInt();

        int count = 0;
        long power = 1;
        while (power <= N) {
            power *= K;
            count++;
        }
        power /= K;

        int[] digits = new int[count];
        long tempN = N;
        long tempPower = power;
        for (int i = 0; i < count; i++) {
            digits[i] = (int)(tempN / tempPower);
            tempN %= tempPower;
            tempPower /= K;
        }

        Matrix[] R = new Matrix[41];
        for (int i = 0; i <= 40; i++) {
            R[i] = new Matrix(0, 0);
        }
        for (int i = 0; i <= K; i++) {
            R[i] = new Matrix(K + 1, K + 1);
            initializeMatrix(R[i], K + 1, K + 1);
        }

        Matrix[][] D = new Matrix[101][40];
        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j < 40; j++) {
                D[i][j] = new Matrix(0, 0);
            }
        }
        for (int i = 0; i <= count; i++) {
            for (int j = 0; j < K; j++) {
                D[i][j] = new Matrix(K + 1, K + 1);
                initializeMatrix(D[i][j], K + 1, K + 1);
            }
        }

        R[0].data[K][K] = 1;
        R[1].data[K][K] = 1;
        for (int j = 0; j < K; j++) {
            R[0].data[j][j] = 1;
        }
        for (int j = 0; j < K; j++) {
            R[1].data[(j + K - 1) % K][j] = 1;
        }
        for (int j = 2; j <= K; j++) {
            R[j] = Matrix.multiply(R[j - 1], R[1]);
        }

        for (int j = 0; j <= K; j++) {
            for (int j2 = 0; j2 < K + 1; j2++) {
                for (int j3 = 0; j3 < K + 1; j3++) {
                    D[0][0].data[j2][j3] = 0;
                }
            }
            D[0][0].data[j][j] = 1;
            D[0][0].data[j][0] = 1;
        }

        int total_count = count;
        for (int i = 0; i <= total_count; i++) {
            for (int j = 1; j < K; j++) {
                D[i][j] = Matrix.multiply(Matrix.multiply(R[K - j], D[i][0]), R[j]);
            }
            if (i + 1 <= total_count) {
                D[i + 1][0] = D[i][K - 1];
            }
        }

        Matrix answer = new Matrix(1, K + 1);
        answer.data[0][K] = 1;
        int mod_acc = 0;

        for (int i = 0; i < total_count; i++) {
            if (digits[i] != 0) {
                Matrix temp1 = Matrix.multiply(R[K - mod_acc], D[total_count - i - 1][digits[i] - 1]);
                answer = Matrix.multiply(temp1, R[mod_acc]);
            }
            mod_acc += digits[i];
            mod_acc %= K;
        }

        long total_res = 0;
        for (int i = 0; i <= K; i++) {
            total_res += answer.data[0][i];
        }
        System.out.println(total_res);
        sc.close();
    }
}
